#define TINYGLTF_IMPLEMENTATION
#include "tiny_gltf.h"

int main(int argc, char** argv) {
  if (argc < 2) return 1;
  std::ifstream f(argv[1], std::ios::binary);
  std::vector<char> data((std::istreambuf_iterator<char>(f)), std::istreambuf_iterator<char>());
